/** Player pick/place packets, neighbouring rotating columns and live joining dialogs. */
@SideOnly(Side.CLIENT)
public final class ArmPlacementLiveChecks {
    private static final EnumFacing[] WALLS={EnumFacing.NORTH,EnumFacing.EAST,EnumFacing.SOUTH,EnumFacing.WEST};
    private static int fixture=Integer.getInteger("vandorlabs.armPlacementStart",0),stage,ticks;
    private static final int END=Integer.getInteger("vandorlabs.armPlacementLimit",42);
    private static final java.util.List<Throwable> failures=new java.util.ArrayList<>();
    private static ItemStack picked;
    private static int window;
    private static BlockPos root(){return new BlockPos(1407+fixture*32,100,0);}
    private static EnumFacing face(){return fixture<12?EnumFacing.values()[fixture%6]:WALLS[fixture%4];}
    private static EnumFacing sourceFace(){return WALLS[fixture%4];}
    private static GearBlock block(){boolean regular=fixture>=34?fixture<38:fixture>=22?fixture<28:fixture<6||fixture>=12&&fixture<16;return regular?GearRegistry.GEAR_SWING_ARM:GearRegistry.LARGE_GEAR_SWING_ARM;}
    private static BlockPos across(){return ArmOrientation.vector(face(),new BlockPos(1,0,0));}
    private static BlockPos column(int n){return root().add(across().getX()*n*block().sizeClass(),across().getY()*n*block().sizeClass(),across().getZ()*n*block().sizeClass());}
    private static void require(boolean ok,String why){if(!ok)throw new IllegalStateException("arm-placement fixture="+fixture+" stage="+stage+" tick="+ticks+" face="+face()+": "+why);}
    private static EntityPlayerMP player(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayers().get(0);}
    private static void look(EntityPlayerMP player,BlockPos at,EnumFacing face){Vec3d center=new Vec3d(at).addVector(.5,.5,.5),eye=center.add(new Vec3d(face.getDirectionVec()).scale(3));Vec3d d=center.subtract(eye);player.connection.setPlayerLocation(eye.x,eye.y-player.getEyeHeight(),eye.z,(float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));}
    private static void place(WorldServer w,EntityPlayerMP p,BlockPos at,EnumFacing face,GearBlock block){p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(block,2));require(p.getHeldItemMainhand().onItemUse(p,w,at.offset(face.getOpposite()),EnumHand.MAIN_HAND,face,.5F,.5F,.5F)==EnumActionResult.SUCCESS,"normal arm placement");}
    private static boolean next(){System.out.println("[vandorlabs] arm-placement case PASS fixture="+fixture+" face="+face());fixture++;stage=ticks=0;return false;}
    public static boolean tick(Minecraft mc)throws Exception{
        if(fixture>=END){if(!failures.isEmpty()){IllegalStateException error=new IllegalStateException("Arm placement failed cases="+failures.size());for(Throwable failure:failures)error.addSuppressed(failure);throw error;}System.out.println("[vandorlabs] arm-placement PASS cases=42 actual middle pick copied stack wall placement client/server axes twelve cases; eight three-column rotating frames; two live Join Arms dialogs controller handoff range packets removal; twelve mismatched neighbours and eight dismantled columns");return true;}
        try{require(++ticks<260,"bounded interaction; client mode="+mc.playerController.getCurrentGameType()+" slot="+mc.player.inventory.currentItem+" held="+mc.player.getHeldItemMainhand()+" screen="+mc.currentScreen);return fixture<12?copy(mc):fixture<20?frame(mc):fixture<22?dialog(mc):fixture<34?mismatch(mc):orphan(mc);}
        catch(Exception failure){System.err.println("[vandorlabs] arm-placement case FAILED fixture="+fixture);failure.printStackTrace();failures.add(failure);fixture++;stage=ticks=0;mc.displayGuiScreen(null);return false;}
    }
    private static void setup(Minecraft mc)throws Exception{
        mc.displayGuiScreen(null);mc.getIntegratedServer().callFromMainThread(()->{
            WorldServer w=mc.getIntegratedServer().getWorld(0);EntityPlayerMP p=player(mc);p.closeScreen();p.setGameType(GameType.CREATIVE);p.capabilities.isFlying=true;p.sendPlayerAbilities();p.inventory.currentItem=0;
            for(BlockPos at:BlockPos.getAllInBox(root().add(-5,-5,-5),root().add(13,5,5))){w.getChunkFromBlockCoords(at);w.removeTileEntity(at);w.setBlockToAir(at);}
            return null;
        }).get();
    }
    private static boolean copy(Minecraft mc)throws Exception{
        BlockPos destination=root().east(8),support=destination.offset(face().getOpposite());
        if(stage==0){setup(mc);mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);EntityPlayerMP p=player(mc);w.setBlockState(root().offset(sourceFace().getOpposite()),Blocks.STONE.getDefaultState(),2);w.setBlockState(support,Blocks.STONE.getDefaultState(),2);place(w,p,root(),sourceFace(),block());GearTileEntity arm=(GearTileEntity)w.getTileEntity(root());require(arm.rebuild(),"source forms");NBTTagCompound settings=arm.settings();settings.setInteger("Direction",fixture%4);settings.setBoolean("RotatePayload",fixture%2==0);settings.setString("Channels","8191");settings.setBoolean("JoinArms",true);settings.setInteger("JoinRange",4);arm.configure(settings);BlockPos neighbour=destination.add(ArmOrientation.vector(face(),new BlockPos(4,0,0)));w.setBlockState(neighbour.offset(face().getOpposite()),Blocks.STONE.getDefaultState(),2);place(w,p,neighbour,face(),block());p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(block()));require(p.getHeldItemMainhand().onItemUse(p,w,neighbour,EnumHand.MAIN_HAND,face(),.5F,.5F,.5F)==EnumActionResult.SUCCESS,"different-length neighbouring column");GearTileEntity other=(GearTileEntity)w.getTileEntity(neighbour);require(other.rebuild(),"neighbour forms before opting in");other.configure(settings);p.setHeldItem(EnumHand.MAIN_HAND,ItemStack.EMPTY);p.inventoryContainer.detectAndSendChanges();look(p,root(),sourceFace());return null;}).get();stage=1;ticks=0;return false;}
        if(stage==1){GearTileEntity source=mc.world.getTileEntity(root()) instanceof GearTileEntity?(GearTileEntity)mc.world.getTileEntity(root()):null;if(ticks<15||source==null||source.mountDirection()!=sourceFace()||!source.isOperational()||mc.playerController.getCurrentGameType()!=GameType.CREATIVE||mc.player.inventory.currentItem!=0||!mc.player.getHeldItemMainhand().isEmpty())return false;require(source.progress()==1,"pick source is extended at construction pose");RayTraceResult hit=new RayTraceResult(new Vec3d(root()).addVector(.5,.5,.5),sourceFace(),root());require(net.minecraftforge.common.ForgeHooks.onPickBlock(hit,mc.player,mc.world),"actual Forge middle-click hook");picked=mc.player.getHeldItemMainhand().copy();require(picked.getItem()==Item.getItemFromBlock(block())&&picked.getSubCompound("ModularGearSettings")!=null,"picked configured arm stack");stage=2;ticks=0;return false;}
        if(stage==2){boolean ready=mc.getIntegratedServer().callFromMainThread(()->{EntityPlayerMP p=player(mc);if(!ItemStack.areItemStacksEqual(p.getHeldItemMainhand(),picked))return false;look(p,destination,face());return true;}).get();if(!ready)return false;stage=3;ticks=0;return false;}
        if(stage==3){Vec3d eye=new Vec3d(destination).addVector(.5,.5,.5).add(new Vec3d(face().getDirectionVec()).scale(3));if(mc.player.getPositionEyes(1).squareDistanceTo(eye)>.1)return false;Vec3d hit=new Vec3d(support).addVector(.5,.5,.5).add(new Vec3d(face().getDirectionVec()).scale(.5));require(mc.playerController.processRightClickBlock(mc.player,mc.world,support,face(),hit,EnumHand.MAIN_HAND)==EnumActionResult.SUCCESS,"place actual picked stack on new support");stage=4;ticks=0;return false;}
        if(ticks<25)return false;
        mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);GearTileEntity arm=(GearTileEntity)w.getTileEntity(destination);require(arm!=null&&arm.mountDirection()==face(),"server copied arm mounts on destination face; actual="+(arm==null?"missing":arm.mountDirection()) );require(arm.isOperational()&&arm.progress()==1,"copied extended arm forms at rest: "+arm.error());require(arm.settings().getString("Channels").equals("8191"),"copied channel settings retained");return null;}).get();GearTileEntity client=(GearTileEntity)mc.world.getTileEntity(destination);require(client!=null&&client.mountDirection()==face()&&client.isOperational()&&client.progress()==1,"client observes correctly mounted copied arm at rest");return next();
    }
    private static void frameSetup(Minecraft mc,boolean neighboursJoin)throws Exception{
        setup(mc);mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);EntityPlayerMP p=player(mc);
            for(int x=-1;x<=2*block().sizeClass()+1;x++)for(int z=-1;z<=1;z++)w.setBlockState(root().add(ArmOrientation.vector(face(),new BlockPos(x,1,z))),Blocks.STONE.getDefaultState(),2);
            for(int n=0;n<3;n++){place(w,p,column(n),face(),block());p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(block()));require(p.getHeldItemMainhand().onItemUse(p,w,column(n),EnumHand.MAIN_HAND,face(),.5F,.5F,.5F)==EnumActionResult.SUCCESS,"second rotating section");GearTileEntity arm=(GearTileEntity)w.getTileEntity(column(n));require(arm.rebuild(),"two-section column forms");NBTTagCompound settings=arm.settings();settings.setInteger("Direction",0);settings.setBoolean("RotatePayload",false);settings.setBoolean("JoinArms",neighboursJoin&&n<2);settings.setInteger("JoinRange",4);arm.configure(settings);w.setBlockState(column(n).offset(face(),2),Blocks.STONE.getDefaultState(),2);}
            for(int x=0;x<=2*block().sizeClass();x++)w.setBlockState(root().add(ArmOrientation.vector(face(),new BlockPos(x,-2,0))),Blocks.STONE.getDefaultState(),2);
            // The payload strip and bordering post touch the supporting frame.
            for(int depth=0;depth<=2;depth++)w.setBlockState(root().add(ArmOrientation.vector(face(),new BlockPos(2*block().sizeClass()+block().sizeClass(),-depth,0))),Blocks.COBBLESTONE.getDefaultState(),2);
            p.setHeldItem(EnumHand.MAIN_HAND,ItemStack.EMPTY);p.inventoryContainer.detectAndSendChanges();look(p,column(2),face());return null;}).get();
    }
    private static boolean frame(Minecraft mc)throws Exception{
        BlockPos armPos=column(2),source=armPos.offset(face(),2);
        if(stage==0){frameSetup(mc,false);if(block().sizeClass()==2)mc.getIntegratedServer().callFromMainThread(()->{for(int n=0;n<3;n++){GearTileEntity a=(GearTileEntity)player(mc).world.getTileEntity(column(n));NBTTagCompound v=a.settings();v.setBoolean("JoinArms",true);a.configure(v);}return null;}).get();stage=1;ticks=0;return false;}
        if(stage==1){if(ticks<15||mc.playerController.getCurrentGameType()!=GameType.CREATIVE||!mc.player.getHeldItemMainhand().isEmpty()||mc.player.inventory.currentItem!=0||mc.world.getBlockState(source).getBlock()!=Blocks.STONE)return false;mc.player.connection.sendPacket(new CPacketPlayerTryUseItemOnBlock(armPos,face(),EnumHand.MAIN_HAND,.5F,.5F,.5F));stage=2;ticks=0;return false;}
        boolean ready=mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);GearTileEntity arm=((GearTileEntity)w.getTileEntity(armPos)).loadedController();require(arm!=null,"selected column retains a controller");if(stage==2){if(ticks>12)require(!arm.target(),"right-click retains motion request: "+arm.error());if(arm.progress()!=0||ArmTransactions.locked(w,arm.getPos()))return false;require(arm.payload()!=null&&arm.payload().blocks.cells.size()==(block().sizeClass()==2?5:1)&&w.isAirBlock(source),"Rotating Arm owns exactly the selected tip/platform");if(block().sizeClass()==1)for(int n=0;n<2;n++)require(w.getBlockState(column(n).offset(face(),2)).getBlock()==Blocks.STONE&&((GearTileEntity)w.getTileEntity(column(n))).progress()==1,"unjoined neighbours remain stationary");return true;}if(arm.progress()!=1||ArmTransactions.locked(w,arm.getPos()))return false;require(w.getBlockState(source).getBlock()==Blocks.STONE,"reverse restores tip once");return true;}).get();if(!ready)return false;if(stage==2){mc.player.connection.sendPacket(new CPacketPlayerTryUseItemOnBlock(armPos,face(),EnumHand.MAIN_HAND,.5F,.5F,.5F));stage=3;ticks=0;return false;}return next();
    }
    private static boolean dialog(Minecraft mc)throws Exception{
        BlockPos access=column(2);
        if(stage==0){frameSetup(mc,fixture==21);mc.getIntegratedServer().callFromMainThread(()->{EntityPlayerMP p=player(mc);p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(com.vandorlabs.items.ModItems.CONFIGURIZER));p.inventoryContainer.detectAndSendChanges();return null;}).get();stage=1;ticks=0;return false;}
        if(stage==1){if(ticks<15||mc.player.getHeldItemMainhand().getItem()!=com.vandorlabs.items.ModItems.CONFIGURIZER)return false;mc.player.connection.sendPacket(new CPacketPlayerTryUseItemOnBlock(access,face(),EnumHand.MAIN_HAND,.5F,.5F,.5F));stage=2;ticks=0;return false;}
        if(stage==2){if(!(mc.currentScreen instanceof GuiModularGear))return false;GuiModularGear gui=(GuiModularGear)mc.currentScreen;window=gui.inventorySlots.windowId;java.util.List<net.minecraft.client.gui.GuiButton> buttons=net.minecraftforge.fml.relauncher.ReflectionHelper.getPrivateValue(net.minecraft.client.gui.GuiScreen.class,gui,"buttonList","field_146292_n");net.minecraft.client.gui.GuiButton join=buttons.stream().filter(b->b.id==9).findFirst().get();require(join.enabled,"Join Arms option enabled");gui.mouseClicked(join.x+5,join.y+5,0);stage=3;ticks=0;return false;}
        if(ticks<30)return false;require(mc.currentScreen instanceof GuiModularGear&&mc.player.openContainer.windowId==window,"joining must retain the open dialog and window");
        if(stage==3){mc.getIntegratedServer().callFromMainThread(()->{EntityPlayerMP p=player(mc);require(p.openContainer instanceof ContainerModularGear&&p.openContainer.windowId==window&&p.openContainer.canInteractWith(p),"server retains authorized dialog after controller rebuild");GearTileEntity arm=((GearTileEntity)p.world.getTileEntity(access)).loadedController();require(arm!=null&&arm.joinEnabled()&&arm.columns().size()==(fixture==21?3:1),"join group formed");return null;}).get();GuiModularGear gui=(GuiModularGear)mc.currentScreen;java.util.List<net.minecraft.client.gui.GuiButton> buttons=net.minecraftforge.fml.relauncher.ReflectionHelper.getPrivateValue(net.minecraft.client.gui.GuiScreen.class,gui,"buttonList","field_146292_n");net.minecraftforge.fml.client.config.GuiSlider range=(net.minecraftforge.fml.client.config.GuiSlider)buttons.stream().filter(b->b.id==10).findFirst().get();gui.mouseClicked(range.x+range.width-1,range.y+10,0);range.mouseReleased(range.x+range.width-1,range.y+10);stage=4;ticks=0;return false;}
        mc.getIntegratedServer().callFromMainThread(()->{EntityPlayerMP p=player(mc);GearTileEntity arm=((GearTileEntity)p.world.getTileEntity(access)).loadedController();require(arm.joinRange()==32,"range packet reaches current controller through original window");p.world.setBlockToAir(access);require(!p.openContainer.canInteractWith(p),"actual access-block removal still invalidates dialog");return null;}).get();mc.displayGuiScreen(null);return next();
    }
    private static boolean mismatch(Minecraft mc)throws Exception{
        if(stage==0){frameSetup(mc,false);mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);EntityPlayerMP p=player(mc);for(int n=0;n<3;n++){GearTileEntity arm=(GearTileEntity)w.getTileEntity(column(n));NBTTagCompound value=arm.settings();value.setBoolean("JoinArms",true);value.setInteger("JoinRange",4);if(n==2){switch((fixture-22)%6){case 0:w.setBlockToAir(column(2).offset(face()));break;case 1:w.setBlockToAir(column(2).offset(face(),2));p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(block()));require(p.getHeldItemMainhand().onItemUse(p,w,column(2).offset(face()),EnumHand.MAIN_HAND,face(),.5F,.5F,.5F)==EnumActionResult.SUCCESS,"longer unmatched column");break;case 2:value.setInteger("Direction",1);break;case 3:value.setBoolean("RotatePayload",true);break;case 4:value.setString("Channels","8192");break;case 5:value.setInteger("Trigger",1);break;}}arm.configure(value);}return null;}).get();stage=1;ticks=0;return false;}
        if(ticks<30)return false;mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);GearTileEntity arm=((GearTileEntity)w.getTileEntity(column(0))).loadedController();require(arm!=null&&arm.isOperational()&&arm.columns().size()==2,"join the two matching columns while ignoring mismatched edge arm; error="+((GearTileEntity)w.getTileEntity(column(0))).error());require(!arm.members().contains(column(2)),"mismatched arm retains independent ownership");return null;}).get();return next();
    }
    private static boolean orphan(Minecraft mc)throws Exception{
        if(stage==0){frameSetup(mc,true);mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);EntityPlayerMP p=player(mc);require(p.interactionManager.tryHarvestBlock(column(0)),"normal harvest dismantles the first mount");return null;}).get();stage=1;ticks=0;return false;}
        if(ticks<30)return false;mc.getIntegratedServer().callFromMainThread(()->{WorldServer w=mc.getIntegratedServer().getWorld(0);BlockPos remains=column(0).offset(face());require(w.getBlockState(remains).getBlock()==block(),"remaining arm still present");net.minecraft.block.state.IBlockState state=w.getBlockState(remains);Vec3d center=new Vec3d(remains).addVector(.5,.5,.5),normal=new Vec3d(face().getDirectionVec());require(state.getBlock().collisionRayTrace(state,w,remains,center.add(normal.scale(2)),center.subtract(normal.scale(2)))!=null,"remaining arm has a native ray target");require(!w.getCollisionBoxes(null,new AxisAlignedBB(remains).shrink(.05)).isEmpty(),"remaining arm has physical collision");require(!state.getBlock().isReplaceable(w,remains),"remaining logical arm cell cannot be replaced");return null;}).get();
        GearTileEntity member=(GearTileEntity)mc.world.getTileEntity(column(0).offset(face()));if(member==null||member.loadedController()==null)return false;
        GearTileEntity controller=member.loadedController();NBTTagCompound saved=controller.writeToNBT(new NBTTagCompound()),inert=saved.copy();inert.setBoolean("GearOperational",false);controller.readFromNBT(inert);
        try{RayTraceResult hit=new RayTraceResult(new Vec3d(member.getPos()).addVector(.5,.5,.5),face(),member.getPos());net.minecraftforge.client.event.DrawBlockHighlightEvent event=new net.minecraftforge.client.event.DrawBlockHighlightEvent(mc.renderGlobal,mc.player,hit,0,1);new OffsetTrapdoorSelection().highlight(event);require(!event.isCanceled(),"inert remaining arm retains vanilla source-cell selection outline");}finally{controller.readFromNBT(saved);}return next();
    }
    private ArmPlacementLiveChecks(){}
}
